package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.CentroCustoRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class CentroCustoApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final CentroCustoRepository r; final OrganizacaoEclesialRepository o; public CentroCustoApplicationService(CentroCustoRepository r,OrganizacaoEclesialRepository o){this.r=r;this.o=o;} @Transactional public CentroCusto criar(CentroCustoRequest x){if(seguranca!=null)seguranca.validarAcesso(x.organizacaoEclesialUuid());var org=o.findByUuid(x.organizacaoEclesialUuid()).orElseThrow();var e=new CentroCusto();e.setOrganizacaoEclesialId(org.getId());e.setCodigo(x.codigo().trim());e.setNome(x.nome().trim());e.setAtivo(x.ativo()==null||x.ativo());return r.save(e);} @Transactional(readOnly=true) public List<CentroCusto> listar(){return r.findAllByOrderByNomeAsc().stream().filter(e -> { try { if(seguranca!=null)seguranca.validarAcessoId(e.getOrganizacaoEclesialId()); return true; } catch (org.springframework.security.access.AccessDeniedException ex) { return false; }}).toList();}}